/***
 * MARK: updateManifest
 * @description Release-manifest schema + semver helpers for the runner
 *   self-update channel (Option A, ADR 0012). The manifest is the only
 *   trusted version pointer: it is signature-verified BEFORE parsing for
 *   control flow (see verify.js), and every asset carries a sha256 the
 *   downloader re-checks after fetch. Pure helpers, no network here.
 * @example validateManifest({ schema: 1, component: 'runner', ... }) => { ok: true }
 ***/
export const MANIFEST_SCHEMA_VERSION = 1;
export const DEFAULT_RELEASES_LATEST_URL =
	"https://api.github.com/repos/Ewrdad/Kainbain/releases/latest";

const SEMVER_RE = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/;

export const parseVersion = (version) => {
	const match = SEMVER_RE.exec(String(version || "").trim());
	if (!match) return null;
	return {
		major: Number(match[1]),
		minor: Number(match[2]),
		patch: Number(match[3]),
		prerelease: match[4] || null,
	};
};

export const isValidVersion = (version) => parseVersion(version) !== null;

// -1 when a<b, 0 when equal, 1 when a>b. A release beats its own
// prerelease (1.2.3 > 1.2.3-rc.1); prerelease-to-prerelease compares
// lexically on the prerelease tag (good enough for skip/newer gates).
export const compareVersions = (a, b) => {
	const pa = parseVersion(a);
	const pb = parseVersion(b);
	if (!pa || !pb) return null;
	for (const key of ["major", "minor", "patch"]) {
		if (pa[key] !== pb[key]) return pa[key] < pb[key] ? -1 : 1;
	}
	if (pa.prerelease === pb.prerelease) return 0;
	if (pa.prerelease === null) return 1;
	if (pb.prerelease === null) return -1;
	return pa.prerelease < pb.prerelease ? -1 : 1;
};

export const isNewerVersion = (candidate, current) => {
	const cmp = compareVersions(candidate, current);
	return cmp === 1;
};

// GitHub marks canary releases as pre-release; v1 runners never install
// them (survey q7: no pre-release opt-in). A manifest whose version is a
// prerelease, or a releases/latest pointer flagged prerelease, is skipped.
export const isPrereleaseVersion = (version) => {
	const parsed = parseVersion(version);
	if (!parsed) return false;
	return parsed.prerelease !== null;
};

const SHA256_RE = /^[0-9a-f]{64}$/i;

export const validateManifest = (manifest) => {
	if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) {
		return { ok: false, reason: "Manifest must be a JSON object." };
	}
	if (manifest.schema !== MANIFEST_SCHEMA_VERSION) {
		return { ok: false, reason: `Unsupported manifest schema ${String(manifest.schema)} (want ${MANIFEST_SCHEMA_VERSION}).` };
	}
	if (manifest.component !== "runner") {
		return { ok: false, reason: `Manifest component must be 'runner', got ${String(manifest.component)}.` };
	}
	if (!isValidVersion(manifest.version)) {
		return { ok: false, reason: `Manifest version is not semver: ${String(manifest.version)}.` };
	}
	if (!Array.isArray(manifest.assets) || manifest.assets.length === 0) {
		return { ok: false, reason: "Manifest must list at least one asset." };
	}
	for (const asset of manifest.assets) {
		if (!asset || typeof asset !== "object") return { ok: false, reason: "Manifest asset must be an object." };
		for (const field of ["platform", "arch", "filename", "sha256", "size"]) {
			if (asset[field] === undefined || asset[field] === null || asset[field] === "") {
				return { ok: false, reason: `Manifest asset is missing '${field}'.` };
			}
		}
		if (!SHA256_RE.test(String(asset.sha256))) {
			return { ok: false, reason: `Manifest asset '${asset.filename}' has a malformed sha256.` };
		}
		if (!Number.isInteger(asset.size) || asset.size <= 0) {
			return { ok: false, reason: `Manifest asset '${asset.filename}' has an invalid size.` };
		}
	}
	return { ok: true };
};

export const assetForPlatform = (manifest, { platform, arch }) => {
	const assets = Array.isArray(manifest?.assets) ? manifest.assets : [];
	return assets.find((a) => a?.platform === platform && a?.arch === arch) || null;
};

// Resolves where to fetch manifest.json / .minisig / asset bytes from.
// A full override URL ending in manifest.json (or /manifest.json) is used
// as-is (air-gapped mirror); otherwise the override is a base and the
// filenames are appended. The default GitHub API pointer is handled by
// the check flow (release assets), not here.
export const resolveUpdateUrls = ({ updateUrl, assetFilename }) => {
	const base = String(updateUrl || "").trim().replace(/\/+$/, "");
	if (!base) return null;
	if (base.endsWith("manifest.json")) {
		const prefix = base.slice(0, -"manifest.json".length);
		return {
			manifestUrl: base,
			signatureUrl: `${prefix}manifest.json.minisig`,
			assetUrl: assetFilename ? `${prefix}${assetFilename}` : null,
		};
	}
	return {
		manifestUrl: `${base}/manifest.json`,
		signatureUrl: `${base}/manifest.json.minisig`,
		assetUrl: assetFilename ? `${base}/${assetFilename}` : null,
	};
};

import fs from "node:fs";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import { verifyAssetBytes, verifyAssetFile } from "./verify.js";

/***
 * MARK: updateDownload
 * @description Atomic asset download for the runner self-update channel
 *   (Option A, ADR 0012). Bytes stream to `<name>.part`, the sha256 is
 *   verified from the completed file, and only then is it renamed into
 *   place — a failed or tampered download never leaves a half-written
 *   asset behind. No extraction here (see index.js apply step).
 * @example await downloadVerifiedAsset({ url, destDir, filename, expectedSha256, fetchImpl }) => { path }
 ***/
export const downloadVerifiedAsset = async ({
	url,
	destDir,
	filename,
	expectedSha256,
	fetchImpl = fetch,
	fsImpl = fs,
} = {}) => {
	if (!url) throw Object.assign(new Error("downloadVerifiedAsset needs a url."), { code: "INVALID_ARGS" });
	if (!filename) throw Object.assign(new Error("downloadVerifiedAsset needs a filename."), { code: "INVALID_ARGS" });
	fsImpl.mkdirSync(destDir, { recursive: true });
	const finalPath = path.join(destDir, filename);
	const partPath = `${finalPath}.part`;
	const res = await fetchImpl(url, { headers: { accept: "application/octet-stream" } });
	if (!res || res.ok !== true) {
		throw Object.assign(new Error(`Asset download failed: HTTP ${res?.status ?? "no-response"} for ${url}.`), {
			code: "DOWNLOAD_FAILED",
			statusCode: typeof res?.status === "number" ? res.status : 502,
		});
	}
	try {
		if (typeof res.arrayBuffer === "function") {
			const bytes = Buffer.from(await res.arrayBuffer());
			const check = verifyAssetBytes({ bytes, expectedSha256 });
			if (!check.ok) {
				throw Object.assign(new Error(`Asset verification failed: ${check.reason}`), { code: "ASSET_SHA_MISMATCH" });
			}
			fsImpl.writeFileSync(partPath, bytes);
		} else if (res.body && typeof res.body.pipe === "function") {
			const out = fsImpl.createWriteStream(partPath);
			await pipeline(res.body, out);
			// Streamed path: verify from the completed file.
			const fileCheck = await verifyAssetFile({ filePath: partPath, expectedSha256 });
			if (!fileCheck.ok) {
				throw Object.assign(new Error(`Asset verification failed: ${fileCheck.reason}`), { code: "ASSET_SHA_MISMATCH" });
			}
		} else {
			throw Object.assign(new Error("Fetch implementation returned no readable body."), { code: "DOWNLOAD_FAILED" });
		}
	} catch (err) {
		if (err?.code === "ASSET_SHA_MISMATCH") throw err;
		try { fsImpl.rmSync(partPath, { force: true }); } catch { /* ignore */ }
		throw Object.assign(new Error(`Asset download failed: ${err?.message || err}.`), { code: "DOWNLOAD_FAILED" });
	}
	fsImpl.renameSync(partPath, finalPath);
	return { path: finalPath };
};

export const fetchText = async ({ url, fetchImpl = fetch, accept = "application/json" } = {}) => {
	const res = await fetchImpl(url, { headers: { accept } });
	if (!res || res.ok !== true) {
		throw Object.assign(new Error(`Fetch failed: HTTP ${res?.status ?? "no-response"} for ${url}.`), {
			code: "FETCH_FAILED",
			statusCode: typeof res?.status === "number" ? res.status : 502,
		});
	}
	if (typeof res.text === "function") return res.text();
	if (typeof res.json === "function" && accept.includes("json")) {
		const data = await res.json();
		return typeof data === "string" ? data : JSON.stringify(data);
	}
	throw Object.assign(new Error("Fetch implementation returned no readable body."), { code: "FETCH_FAILED" });
};

import crypto from "node:crypto";
import fs from "node:fs";

/***
 * MARK: updateVerify
 * @description Signature + integrity verification for the runner self-update
 *   channel (Option A, ADR 0012, R05). Trust root: the minisign PUBLIC key
 *   pinned below. It is compiled into the runner source — NEVER fetched from
 *   the network, never taken from a downloaded file. Compromise of the
 *   backend, the GitHub API, or the asset store alone cannot ship a runner
 *   binary: the updater aborts unless the manifest carries a valid
 *   signature from this key, and aborts unless the asset matches the
 *   manifest's sha256. Verification order is fixed: signature → schema →
 *   sha256. Rotation happens only via a new runner release signed by the
 *   old key (or a fresh bootstrap install).
 * @example await verifyManifestSignature({ manifestBytes, signatureText }) => { ok: true }
 ***/

// Kainbain runner release signing key (verify-only public half).
// The secret half lives in the GitHub Actions secret
// RUNNER_RELEASE_SIGNING_KEY; this constant must never be replaced by a
// value read from disk, config, or the network at runtime.
// Provisioning: run `node scripts/runner-release-keygen.mjs` ONCE, commit
// the printed public line here (and in scripts/runner-pinned-key/
// runner-release.pub — CI fails the release when they differ), and store
// the secret halves in GitHub Actions secrets. The value below is the
// initial placeholder: replace it before cutting the first real release,
// otherwise runners will reject that release's manifest signature.
export const PINNED_RELEASE_PUBLIC_KEY =
	"RWR8CRkuyEfBxwUaaAnqo8ZXL7XgO8G2H8ZhAe6YoOr7+EfDVsoWznZG";
export const PINNED_RELEASE_KEYNUM = "7c09192ec847c1c7";

const MINISIGN_SIG_ALG = "Ed";

const decodeMinisignPub = (keyText) => {
	const line = String(keyText || "")
		.split("\n")
		.map((l) => l.trim())
		.filter((l) => l && !l.startsWith("untrusted comment:"))
		.at(-1);
	if (!line) return { ok: false, reason: "Public key file has no key line." };
	let raw;
	try {
		raw = Buffer.from(line, "base64");
	} catch {
		return { ok: false, reason: "Public key line is not base64." };
	}
	if (raw.length !== 42 || raw.subarray(0, 2).toString("ascii") !== MINISIGN_SIG_ALG) {
		return { ok: false, reason: "Public key is not a minisign Ed25519 key (want 42 bytes, 'Ed' prefix)." };
	}
	return { ok: true, keynum: raw.subarray(2, 10).toString("hex"), pubRaw: raw.subarray(10) };
};

// Returns the GLOBAL signature (over the manifest bytes). A minisign
// .minisig file carries two signatures: the global one (line 2, signs the
// file) and the trusted-comment one (line 4, signs sig+comment for human
// `minisign -V` output). Only the global signature gates an install; the
// trusted-comment signature is verified opportunistically when present.
const decodeMinisignSig = (sigText) => {
	const lines = String(sigText || "")
		.split("\n")
		.map((l) => l.trim())
		.filter(Boolean)
		.filter((l) => !l.startsWith("untrusted comment:"));
	if (lines.length === 0) return { ok: false, reason: "Signature file is empty." };
	let raw;
	try {
		raw = Buffer.from(lines[0], "base64");
	} catch {
		return { ok: false, reason: "Signature line is not base64." };
	}
	if (raw.length !== 74 || raw.subarray(0, 2).toString("ascii") !== MINISIGN_SIG_ALG) {
		return { ok: false, reason: "Signature is not a minisign Ed25519 signature (want 74 bytes, 'Ed' prefix)." };
	}
	return { ok: true, keynum: raw.subarray(2, 10).toString("hex"), sig: raw.subarray(10) };
};

const spkiDerFor = (pubRaw) =>
	Buffer.concat([Buffer.from("302a300506032b6570032100", "hex"), Buffer.from(pubRaw)]);

export const verifyManifestSignature = ({ manifestBytes, signatureText, publicKey = PINNED_RELEASE_PUBLIC_KEY } = {}) => {
	if (!manifestBytes || manifestBytes.length === 0) {
		return { ok: false, reason: "Nothing to verify (empty manifest bytes)." };
	}
	const pub = decodeMinisignPub(publicKey);
	if (!pub.ok) return pub;
	if (pub.keynum !== PINNED_RELEASE_KEYNUM && publicKey === PINNED_RELEASE_PUBLIC_KEY) {
		return { ok: false, reason: "Pinned release key mismatch (source tampered?)." };
	}
	const sig = decodeMinisignSig(signatureText);
	if (!sig.ok) return sig;
	if (sig.keynum !== pub.keynum) {
		return { ok: false, reason: `Signature key id ${sig.keynum} does not match public key id ${pub.keynum}.` };
	}
	let keyObject;
	try {
		keyObject = crypto.createPublicKey({ key: spkiDerFor(pub.pubRaw), format: "der", type: "spki" });
	} catch {
		return { ok: false, reason: "Pinned public key does not parse as Ed25519." };
	}
	let valid = false;
	try {
		valid = crypto.verify(null, Buffer.from(manifestBytes), keyObject, Buffer.from(sig.sig));
	} catch {
		valid = false;
	}
	if (!valid) return { ok: false, reason: "Manifest signature verification FAILED (tampered manifest or wrong key)." };
	return { ok: true, keynum: sig.keynum };
};

export const sha256HexOf = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");

export const verifyAssetBytes = ({ bytes, expectedSha256 }) => {
	const actual = sha256HexOf(bytes || Buffer.alloc(0));
	const expected = String(expectedSha256 || "").trim().toLowerCase();
	if (!/^[0-9a-f]{64}$/.test(expected)) return { ok: false, reason: "Expected sha256 is malformed.", actual };
	let match = false;
	try {
		match = crypto.timingSafeEqual(Buffer.from(actual, "utf8"), Buffer.from(expected, "utf8"));
	} catch {
		match = actual === expected;
	}
	if (!match) return { ok: false, reason: `Asset sha256 mismatch (want ${expected.slice(0, 16)}…, got ${actual.slice(0, 16)}…).`, actual };
	return { ok: true, actual };
};

export const verifyAssetFile = async ({ filePath, expectedSha256 }) => {
	const expected = String(expectedSha256 || "").trim().toLowerCase();
	if (!/^[0-9a-f]{64}$/.test(expected)) return { ok: false, reason: "Expected sha256 is malformed.", actual: null };
	const hash = crypto.createHash("sha256");
	const stream = fs.createReadStream(filePath);
	await new Promise((resolve, reject) => {
		stream.on("data", (chunk) => hash.update(chunk));
		stream.on("end", resolve);
		stream.on("error", reject);
	});
	const digest = hash.digest("hex");
	let match = false;
	try {
		match = crypto.timingSafeEqual(Buffer.from(digest, "utf8"), Buffer.from(expected, "utf8"));
	} catch {
		match = digest === expected;
	}
	if (!match) {
		return { ok: false, reason: `Asset sha256 mismatch (want ${expected.slice(0, 16)}…, got ${digest.slice(0, 16)}…).`, actual: digest };
	}
	return { ok: true, actual: digest };
};

import { execFile } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { assetForPlatform, DEFAULT_RELEASES_LATEST_URL, isNewerVersion, isPrereleaseVersion, resolveUpdateUrls, validateManifest } from "./manifest.js";
import { detectUpdatePlatform } from "./platform.js";
import { verifyManifestSignature } from "./verify.js";
import { downloadVerifiedAsset, fetchText } from "./download.js";
import { acquireUpdateLock, markUpdatePendingBoot, readUpdateState } from "./state.js";

const execFileAsync = promisify(execFile);

/***
 * MARK: updateCheck
 * @description Idle-time update orchestrator for the runner self-update
 *   channel (Option A, ADR 0012). checkForUpdate pulls the release pointer
 *   (GitHub releases/latest or an air-gapped mirror base), verifies the
 *   manifest signature against the PINNED key, and returns the matching
 *   platform asset — never touching the install when nothing is newer or
 *   anything fails. applyUpdate downloads, re-verifies sha256, extracts to
 *   a versioned dir, and atomically flips current/previous symlinks.
 *   The caller (daemon idle branch) guarantees no active task; a lock
 *   guards overlapping invocations.
 * @example await checkForUpdate({ currentVersion: '0.1.0', config }) => { version: '0.2.0', ... } | null
 ***/
export const isGithubReleasesPointer = (updateUrl) =>
	/api\.github\.com\/repos\//.test(String(updateUrl || ""));

export const checkForUpdate = async ({
	currentVersion,
	updateUrl = DEFAULT_RELEASES_LATEST_URL,
	fetchImpl = fetch,
	// Test seam only: production always uses verifyManifestSignature with
	// the pinned key. Tests inject a verifier bound to the TEST key.
	verifyImpl = verifyManifestSignature,
	platform,
	arch,
	logger = console,
} = {}) => {
	const detected = detectUpdatePlatform({ platform, arch });
	if (!detected.ok) {
		logger.warn?.(`Runner update: ${detected.reason} (${platform}/${arch}); skipping check.`);
		return { ok: false, reason: detected.reason };
	}
	let manifestText;
	let signatureText;
	let releaseMeta = null;
	if (isGithubReleasesPointer(updateUrl)) {
		const pointerText = await fetchText({ url: updateUrl, fetchImpl, accept: "application/vnd.github+json" });
		try {
			releaseMeta = JSON.parse(pointerText);
		} catch {
			return { ok: false, reason: "Release pointer is not valid JSON." };
		}
		if (releaseMeta?.prerelease === true || isPrereleaseVersion(releaseMeta?.tag_name)) {
			return { ok: true, update: null, reason: "Latest release is a pre-release; v1 runners skip it." };
		}
		const assets = Array.isArray(releaseMeta?.assets) ? releaseMeta.assets : [];
		const manifestAsset = assets.find((a) => a?.name === "manifest.json");
		const sigAsset = assets.find((a) => a?.name === "manifest.json.minisig");
		if (!manifestAsset?.browser_download_url || !sigAsset?.browser_download_url) {
			return { ok: false, reason: "Latest release has no manifest.json / manifest.json.minisig assets." };
		}
		[manifestText, signatureText] = await Promise.all([
			fetchText({ url: manifestAsset.browser_download_url, fetchImpl, accept: "application/json" }),
			fetchText({ url: sigAsset.browser_download_url, fetchImpl, accept: "text/plain" }),
		]);
	} else {
		const urls = resolveUpdateUrls({ updateUrl });
		[manifestText, signatureText] = await Promise.all([
			fetchText({ url: urls.manifestUrl, fetchImpl, accept: "application/json" }),
			fetchText({ url: urls.signatureUrl, fetchImpl, accept: "text/plain" }),
		]);
	}
	const manifestBytes = Buffer.from(manifestText, "utf8");
	const verified = verifyImpl({ manifestBytes, signatureText });
	if (!verified.ok) return { ok: false, reason: verified.reason };
	let manifest;
	try {
		manifest = JSON.parse(manifestText);
	} catch {
		return { ok: false, reason: "Manifest is not valid JSON." };
	}
	const schema = validateManifest(manifest);
	if (!schema.ok) return { ok: false, reason: schema.reason };
	if (isPrereleaseVersion(manifest.version)) {
		return { ok: true, update: null, manifest, reason: "Manifest version is a pre-release; v1 runners skip it." };
	}
	if (!isNewerVersion(manifest.version, currentVersion)) {
		return { ok: true, update: null, manifest, reason: "Already on the latest version." };
	}
	const asset = assetForPlatform(manifest, { platform: detected.platform, arch: detected.arch });
	if (!asset) {
		return { ok: true, update: null, manifest, reason: `No asset for ${detected.platform}/${detected.arch} in manifest ${manifest.version}.` };
	}
	return { ok: true, update: { version: manifest.version, manifest, asset, releaseMeta }, manifest };
};

const extractTarball = async ({ archivePath, destDir }) => {
	fs.mkdirSync(destDir, { recursive: true });
	await execFileAsync("tar", ["-xzf", archivePath, "-C", destDir]);
};

export const applyUpdate = async ({
	update,
	installRoot,
	updateUrl = DEFAULT_RELEASES_LATEST_URL,
	fetchImpl = fetch,
	extractImpl = extractTarball,
	logger = console,
} = {}) => {
	if (!update?.asset || !update?.manifest) {
		throw Object.assign(new Error("applyUpdate needs a checked update (manifest + asset)."), { code: "INVALID_ARGS" });
	}
	const release = acquireUpdateLock(installRoot);
	if (!release) {
		throw Object.assign(new Error("Another updater holds the update lock."), { code: "UPDATE_IN_PROGRESS" });
	}
	try {
		const versionDir = path.join(installRoot, "releases", update.version);
		let assetUrl;
		if (isGithubReleasesPointer(updateUrl)) {
			const assets = Array.isArray(update.releaseMeta?.assets) ? update.releaseMeta.assets : [];
			assetUrl = assets.find((a) => a?.name === update.asset.filename)?.browser_download_url || null;
		} else {
			assetUrl = resolveUpdateUrls({ updateUrl, assetFilename: update.asset.filename }).assetUrl;
		}
		if (!assetUrl) {
			throw Object.assign(new Error(`No download URL for ${update.asset.filename}.`), { code: "NO_ASSET_URL" });
		}
		const { path: archivePath } = await downloadVerifiedAsset({
			url: assetUrl,
			destDir: versionDir,
			filename: update.asset.filename,
			expectedSha256: update.asset.sha256,
			fetchImpl,
		});
		const unpackedDir = path.join(versionDir, "unpacked");
		fs.rmSync(unpackedDir, { recursive: true, force: true });
		await extractImpl({ archivePath, destDir: unpackedDir });
		// Normalize single-top-level-dir archives (tar convention) so the
		// active tree always has version.json at its root.
		if (!fs.existsSync(path.join(unpackedDir, "version.json"))) {
			const entries = fs.readdirSync(unpackedDir);
			if (entries.length === 1) {
				const inner = path.join(unpackedDir, entries[0]);
				if (fs.statSync(inner).isDirectory() && fs.existsSync(path.join(inner, "version.json"))) {
					const stage = path.join(versionDir, "unpacked.stage");
					fs.rmSync(stage, { recursive: true, force: true });
					fs.renameSync(inner, stage);
					fs.rmSync(unpackedDir, { recursive: true, force: true });
					fs.renameSync(stage, unpackedDir);
				}
			}
		}
		// Sanity: the extracted tree must self-identify as the version we
		// verified. A mismatch means the packager shipped the wrong tree.
		try {
			const extractedVersion = JSON.parse(fs.readFileSync(path.join(unpackedDir, "version.json"), "utf8"));
			const got = String(extractedVersion?.runnerVersion || "").trim().replace(/^v/, "");
			if (got && got !== String(update.version).replace(/^v/, "")) {
				throw new Error(`extracted version.json runnerVersion ${got} != manifest version ${update.version}`);
			}
		} catch (err) {
			if (err?.code === "VERSION_MISMATCH" || /runnerVersion/.test(err?.message || "")) throw err;
			// No version.json in the archive: warn, do not block (dev mirrors).
			logger.warn?.(`Runner update: no version.json in unpacked tree (${err?.message || err}).`);
		}
		fs.writeFileSync(path.join(versionDir, "manifest.json"), JSON.stringify(update.manifest));
		const previousTarget = (() => {
			try { return fs.readlinkSync(path.join(installRoot, "current")); } catch { return null; }
		})();
		markUpdatePendingBoot({ installRoot, from: previousTarget, to: update.version });
		const tmpLink = path.join(installRoot, "current.tmp");
		try { fs.rmSync(tmpLink, { force: true }); } catch { /* ignore */ }
		fs.symlinkSync(unpackedDir, tmpLink);
		fs.renameSync(tmpLink, path.join(installRoot, "current"));
		if (previousTarget && previousTarget !== unpackedDir) {
			const prevLink = path.join(installRoot, "previous.tmp");
			try { fs.rmSync(prevLink, { force: true }); } catch { /* ignore */ }
			fs.symlinkSync(previousTarget, prevLink);
			fs.renameSync(prevLink, path.join(installRoot, "previous"));
		}
		logger.log?.(`Runner update: ${update.version} staged; restart to boot it (rollback kept at previous).`);
		return { ok: true, version: update.version, installRoot, unpackedDir, restartRequired: true };
	} finally {
		release();
	}
};

export const currentUpdateStatus = ({ installRoot } = {}) => readUpdateState(installRoot);

import fs from "node:fs";
import path from "node:path";

/***
 * MARK: updateState
 * @description Durable update-state bookkeeping for the runner self-update
 *   channel (Option A, ADR 0012). State lives beside the install root
 *   (update-state.json): pending-version markers, boot-attempt counters for
 *   failed-boot rollback, and an O_EXCL lock so heartbeat + idle paths can
 *   never run two updaters at once.
 * @example readUpdateState('/opt/runner') => { status: 'idle', ... }
 ***/
export const UPDATE_STATE_FILE = "update-state.json";
export const UPDATE_LOCK_FILE = "update.lock";
export const MAX_BOOT_ATTEMPTS = 3;

export const defaultInstallRoot = ({ workRoot } = {}) => {
	const base = String(workRoot || process.env.KAINBAIN_RUNNER_WORK_ROOT || "runner-work");
	return path.resolve(base, "..", "runner-install");
};

export const readUpdateState = (installRoot) => {
	try {
		const raw = fs.readFileSync(path.join(installRoot, UPDATE_STATE_FILE), "utf8");
		const parsed = JSON.parse(raw);
		if (parsed && typeof parsed === "object") return parsed;
	} catch {
		// Absent or unreadable: idle, never fatal.
	}
	return { status: "idle", bootAttempts: 0 };
};

export const writeUpdateState = (installRoot, state) => {
	fs.mkdirSync(installRoot, { recursive: true });
	const tmp = path.join(installRoot, `${UPDATE_STATE_FILE}.tmp`);
	fs.writeFileSync(tmp, JSON.stringify({ ...state, updatedAt: new Date().toISOString() }));
	fs.renameSync(tmp, path.join(installRoot, UPDATE_STATE_FILE));
};

// Lock so two updater invocations (heartbeat + idle) never overlap. Returns
// a release function, or null when another updater holds the lock.
export const acquireUpdateLock = (installRoot) => {
	fs.mkdirSync(installRoot, { recursive: true });
	const lockPath = path.join(installRoot, UPDATE_LOCK_FILE);
	let fd = null;
	try {
		fd = fs.openSync(lockPath, "wx");
		fs.writeFileSync(fd, String(process.pid));
	} catch {
		return null;
	}
	let released = false;
	return () => {
		if (released) return;
		released = true;
		try { fs.closeSync(fd); } catch { /* already closed */ }
		try { fs.rmSync(lockPath, { force: true }); } catch { /* best effort */ }
	};
};

// Startup gate: called by main.js before the daemon boots. A fresh update
// flips state to pending-boot; only a successful heartbeat (markBooted)
// clears it. Three crashed boots in a row flip current/previous back and
// report rolled-back so the fleet never bricks on a bad release.
export const bootstrapUpdateState = ({ installRoot, readlink = (p) => fs.readlinkSync(p), fsImpl = fs } = {}) => {
	const state = readUpdateState(installRoot);
	if (state.status !== "pending-boot") return { action: "boot", state };
	const attempts = Number(state.bootAttempts || 0) + 1;
	if (attempts >= MAX_BOOT_ATTEMPTS) {
		try {
			const currentTarget = readlink(path.join(installRoot, "current"));
			const previousTarget = readlink(path.join(installRoot, "previous"));
			if (previousTarget && previousTarget !== currentTarget) {
				const tmp = path.join(installRoot, "current.tmp");
				try { fsImpl.rmSync(tmp, { force: true }); } catch { /* ignore */ }
				fsImpl.symlinkSync(previousTarget, tmp);
				fsImpl.renameSync(tmp, path.join(installRoot, "current"));
			}
		} catch {
			// Rollback best-effort: a missing previous link keeps the new
			// version in place and reports instead of crashing boot.
		}
		const rolled = { ...state, status: "rolled-back", bootAttempts: attempts };
		writeUpdateState(installRoot, rolled);
		return { action: "rolled-back", state: rolled };
	}
	const pending = { ...state, status: "pending-boot", bootAttempts: attempts };
	writeUpdateState(installRoot, pending);
	return { action: "boot", state: pending };
};

export const markUpdatePendingBoot = ({ installRoot, from, to }) => {
	writeUpdateState(installRoot, { status: "pending-boot", from, to, bootAttempts: 0 });
};

// Called after the first successful heartbeat on the new version: the
// release boots, so GC may drop everything except current + previous.
export const markUpdateSuccess = ({ installRoot, version }) => {
	writeUpdateState(installRoot, { status: "success", version, bootAttempts: 0 });
};

import semver from "semver";

/***
 * MARK: runnerVersionCompat
 * @description Pure version-compat helpers for the runner self-update
 *   channel (Option A, ADR 0012): the backend never ships runner code, it
 *   only compares the product version Runners report in
 *   `facts.versions.runner` against the operator knobs
 *   KAINBAIN_RUNNER_MIN_VERSION (dispatch floor) and
 *   KAINBAIN_RUNNER_RECOMMENDED_VERSION (fleet-matrix badge). A Runner
 *   that reports no version is permissive on both (never blocked, badge
 *   shows unknown) so introducing the knobs cannot lock the fleet out.
 * @example runnerVersionAtLeast('0.2.0', '0.1.0') => true
 ***/
/***
 * MARK: coerceRunnerVersion
 * @description Normalizes a reported product version to `major.minor.patch`
 *   (tolerates a `v` prefix, coerces partial input). Null when absent or
 *   unparseable — callers treat that as permissive, never a block.
 * @example coerceRunnerVersion('v1.2.3') => '1.2.3'
 ***/
export const coerceRunnerVersion = (version) => {
	if (typeof version !== "string") return null;
	const cleaned = version.trim().replace(/^v/, "");
	if (!cleaned) return null;
	try {
		const coerced = semver.coerce(cleaned);
		return coerced ? coerced.version : null;
	} catch {
		return null;
	}
};

/***
 * MARK: runnerVersionAtLeast
 * @description Whether a reported Runner product version meets a floor.
 *   Permissive (true) when either side is missing or malformed, so
 *   introducing a floor can never lock the fleet out.
 * @example runnerVersionAtLeast('0.2.0', '0.1.0') => true
 ***/
export const runnerVersionAtLeast = (runnerVersion, minVersion) => {
	const have = coerceRunnerVersion(runnerVersion);
	const floor = coerceRunnerVersion(minVersion);
	if (!have) return true;
	if (!floor) return true;
	try {
		return semver.gte(have, floor);
	} catch {
		return true;
	}
};

/***
 * MARK: belowMinimumRunnerVersion
 * @description Whether a KNOWN Runner version sits below the dispatch
 *   floor (the 409 condition). Unknown versions answer false — permissive.
 * @example belowMinimumRunnerVersion('0.0.9', '0.1.0') => true
 ***/
export const belowMinimumRunnerVersion = (runnerVersion, minVersion) => {
	if (coerceRunnerVersion(runnerVersion) === null) return false;
	return !runnerVersionAtLeast(runnerVersion, minVersion);
};

/***
 * MARK: updateAvailableForRunner
 * @description Badge condition for the fleet matrix: true only when both
 *   sides parse and the Runner trails the recommended version.
 * @example updateAvailableForRunner('0.1.0', '0.2.0') => true
 ***/
export const updateAvailableForRunner = (runnerVersion, recommendedVersion) => {
	const have = coerceRunnerVersion(runnerVersion);
	const target = coerceRunnerVersion(recommendedVersion);
	if (!have || !target) return false;
	try {
		return semver.lt(have, target);
	} catch {
		return false;
	}
};

/***
 * MARK: updateInfoForRunner
 * @description Derives the fleet-matrix version fields from heartbeat
 *   facts plus the operator knobs (registry `_public` consumes this).
 * @example updateInfoForRunner({ versions: { runner: '0.1.0' } }, { minVersion: '0.1.0', recommendedVersion: '0.2.0' }) => { runnerVersion: '0.1.0', updateAvailable: true, ... }
 ***/
export const updateInfoForRunner = (facts, { minVersion, recommendedVersion } = {}) => {
	const runnerVersion = facts?.versions?.runner ?? null;
	const updateStatus = facts?.updateStatus ?? null;
	return {
		runnerVersion,
		updateAvailable: updateAvailableForRunner(runnerVersion, recommendedVersion),
		belowMinimum: belowMinimumRunnerVersion(runnerVersion, minVersion),
		minimumVersion: typeof minVersion === "string" && minVersion ? minVersion : null,
		recommendedVersion: typeof recommendedVersion === "string" && recommendedVersion ? recommendedVersion : null,
		updateStatus,
	};
};

