		const got = await checkForUpdate({
			currentVersion: "0.1.0",
			updateUrl: "http://mirror.local/r",
			fetchImpl: mirrorFetch,
			verifyImpl: verifyWithTestKey,
			platform: "linux",
			arch: "x64",
			logger: { warn: () => {}, log: () => {} },
